// the game won't announce these, the real level hasn't moved
public class LevelUpNotifier
{
	private static final String PREFIX = "The Other Half: ";
	private static final int MILESTONE_EVERY = 10;

	// nothing in the api names it, this is what Annoyance Mute silences
	private static final int LEVEL_UP_SOUND = 2396;

	// spotanim table key, 0 is the slot a level up uses
	private static final int SPOTANIM_SLOT = 0;

	// world units, a tile is 128. at 0 it goes off at your feet.
	private static final int SPOTANIM_HEIGHT = 128;

	@Inject
	private Client client;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private TheOtherHalfConfig config;

	// finalLevel lands on the same xp as a real 99, so it gets the loudest one
	public void announce(Skill skill, int level, boolean finalLevel)
	{
		if (config.levelUpMessage())
		{
			postChat(skill, level, finalLevel);
		}

		boolean milestone = finalLevel || level % MILESTONE_EVERY == 0;
		if (config.bigMilestonesOnly() && !milestone)
		{
			return;
		}

		celebrate(milestone ? SpotanimID.LEVELUP_99_ANIM : SpotanimID.LEVELUP_ANIM);
	}

	private void celebrate(int spotanim)
	{
		if (isSuppressed())
		{
			return;
		}

		if (config.levelUpSound())
		{
			client.playSoundEffect(LEVEL_UP_SOUND);
		}

		if (config.levelUpFireworks())
		{
			Player local = client.getLocalPlayer();
			if (local != null)
			{
				local.createSpotAnim(SPOTANIM_SLOT, spotanim, SPOTANIM_HEIGHT, 0);
			}
		}
	}

	private void postChat(Skill skill, int level, boolean finalLevel)
	{
		// no "your" here, Screenshot matches ".*Your (skill) (level is|are)? now (\d+)."
		String text = finalLevel
			? PREFIX + prettyName(skill) + " is now level " + level + ", and that is a real 99."
			: PREFIX + prettyName(skill) + " is now level " + level + ".";

		String formatted = new ChatMessageBuilder()
			.append(config.levelUpColour(), text)
			.build();

		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(formatted)
			.build());
	}

	private boolean isSuppressed()
	{
		if (!config.suppressInCombat())
		{
			return false;
		}

		if (client.isInInstancedRegion())
		{
			return true;
		}

		// health bar only shows in real combat. going off getInteracting would kill
		// this for fishing and mining too.
		Player local = client.getLocalPlayer();
		return local != null && local.getHealthRatio() != -1;
	}

	private static String prettyName(Skill skill)
	{
		String name = skill.name();
		return name.charAt(0) + name.substring(1).toLowerCase(Locale.ROOT);
	}
}

package com.theotherhalf.render;

import com.theotherhalf.BarGoal;
import com.theotherhalf.TheOtherHalfConfig;
import com.theotherhalf.model.LevelModel;
import java.util.EnumMap;
import java.util.Map;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;

// our own widgets on each tile, never edits to the game's
@Slf4j
public class BarRenderer
{
	private static final int INDENT = 3;
	private static final int OPAQUE = 0;

	// same child SkillTabRenderer writes to
	private static final int CHILD_BASE_LEVEL = 5;

	@Inject
	private Client client;

	@Inject
	private TheOtherHalfConfig config;

	// [background, fill] per skill
	private final Map<Skill, Widget[]> bars = new EnumMap<>(Skill.class);

	public void render(LevelModel model, Skill hovered)
	{
		int height = config.barHeight();
		int indent = config.indentToMatchCorners() ? INDENT : 0;
		int fillColour = config.barColour().getRGB() & 0xFFFFFF;
		int backColour = config.barBackgroundColour().getRGB() & 0xFFFFFF;
		boolean realGoal = config.barGoal() == BarGoal.REAL;
		boolean revealOnHover = config.showRealLevel();

		for (Map.Entry<Skill, Integer> entry : SkillTabRenderer.skillWidgets().entrySet())
		{
			Skill skill = entry.getKey();
			Widget parent = client.getWidget(entry.getValue());
			if (parent == null || parent.getWidth() <= 0)
			{
				continue;
			}

			Widget[] pair = attached(parent, bars.get(skill));
			if (pair == null)
			{
				pair = create(parent);
				bars.put(skill, pair);
			}

			int xp = client.getSkillExperience(skill);

			// hovering shows the real goal even when the bar tracks the shown one
			boolean useReal = realGoal || (revealOnHover && skill == hovered);
			LevelModel.Result result = useReal ? model.realFor(xp) : model.forSkill(skill, xp);
			float progress = result.progress(xp);

			int full = Math.max(0, parent.getWidth() - indent * 2);
			int y = barTop(parent, height);

			place(pair[0], indent, y, full, height, backColour);
			place(pair[1], indent, y, Math.round(full * progress), height, fillColour);
		}
	}

	// no way to delete one child, and deleteAllChildren takes the game's too
	public void clear()
	{
		for (Map.Entry<Skill, Widget[]> entry : bars.entrySet())
		{
			// don't let one bad skill strand the rest
			try
			{
				for (Widget widget : entry.getValue())
				{
					if (widget == null)
					{
						continue;
					}

					// hiding alone doesn't repaint, and a leftover size still draws
					widget.setHidden(true);
					widget.setOriginalWidth(0);
					widget.setOriginalHeight(0);
					widget.revalidate();
				}

				// tile owns the layout
				Integer widgetId = SkillTabRenderer.skillWidgets().get(entry.getKey());
				Widget parent = widgetId == null ? null : client.getWidget(widgetId);
				if (parent != null)
				{
					parent.revalidate();
				}

			}
			catch (Exception e)
			{
				log.debug("could not clear the bar on {}", entry.getKey(), e);
			}
		}

		bars.clear();
	}

	// widgets already gone, just drop the refs
	public void reset()
	{
		bars.clear();
	}

	// bottom row is 2px taller and those 2 get clipped, so sit on the base level
	// number rather than the tile height
	private static int barTop(Widget parent, int height)
	{
		int bottom = parent.getHeight();

		Widget baseLevel = parent.getChild(CHILD_BASE_LEVEL);
		if (baseLevel != null && baseLevel.getOriginalHeight() > 0)
		{
			bottom = baseLevel.getOriginalY() + baseLevel.getOriginalHeight();
		}

		return Math.max(0, Math.min(bottom, parent.getHeight() - height));
	}

	// the game appends its own children after ours so position is not fixed.
	// assumed they stayed last once and leaked a pair per rebuild.
	private static Widget[] attached(Widget parent, Widget[] pair)
	{
		if (pair == null || pair[0] == null || pair[1] == null)
		{
			return null;
		}

		Widget[] children = parent.getDynamicChildren();
		if (children == null)
		{
			return null;
		}

		boolean first = false;
		boolean second = false;
		for (Widget child : children)
		{
			if (child == pair[0])
			{
				first = true;
			}
			else if (child == pair[1])
			{
				second = true;
			}
		}

		return first && second ? pair : null;
	}

	private static Widget[] create(Widget parent)
	{
		return new Widget[]{
			parent.createChild(WidgetType.RECTANGLE),
			parent.createChild(WidgetType.RECTANGLE)
		};
	}

	private static void place(Widget widget, int x, int y, int width, int height, int colour)
	{
		if (widget == null)
		{
			return;
		}

		widget.setHidden(width <= 0);
		widget.setOriginalX(x);
		widget.setOriginalY(y);
		widget.setOriginalWidth(width);
		widget.setOriginalHeight(height);
		widget.setTextColor(colour);
		widget.setFilled(true);
		widget.setOpacity(OPAQUE);
		widget.revalidate();
	}
}

package com.theotherhalf.render;

import com.theotherhalf.TheOtherHalfConfig;
import com.theotherhalf.model.LevelModel;
import java.util.Collections;
import java.util.EnumMap;
import java.util.Locale;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

// writes the numbers. LevelModel decides what they are.
public class SkillTabRenderer
{
	// no gameval for these. checked on 1.12.38: 4 is top left, 5 is bottom right.
	private static final int CHILD_CURRENT_LEVEL = 4;
	private static final int CHILD_BASE_LEVEL = 5;

	// tooltip splits labels and numbers into two text children
	private static final int TOOLTIP_LABELS = 2;
	private static final int TOOLTIP_VALUES = 3;
	private static final String LINE_BREAK = "<br>";
	private static final String XP_LABEL = " XP:";

	// we never saw the original, so leave the colour alone
	private static final int NO_COLOUR = -1;

	private static final Map<Skill, Integer> SKILL_WIDGETS = buildSkillWidgets();

	@Inject
	private Client client;

	@Inject
	private TheOtherHalfConfig config;

	// queueChangedSkill rebuilds the text but not the colour, so remember it ourselves
	private final Map<Skill, Integer> vanillaColour = new EnumMap<>(Skill.class);

	public void render(LevelModel model, Skill hovered)
	{
		boolean tintOn = config.tintSecondHalfLevels();
		boolean revealOnHover = config.showRealLevel();
		int tintColour = config.secondHalfColour().getRGB() & 0xFFFFFF;

		for (Map.Entry<Skill, Integer> entry : SKILL_WIDGETS.entrySet())
		{
			Skill skill = entry.getKey();
			if (!isSkillEnabled(skill))
			{
				continue;
			}

			Widget widget = client.getWidget(entry.getValue());
			if (widget == null)
			{
				continue;
			}

			rememberColour(skill, widget, tintColour);

			int xp = client.getSkillExperience(skill);
			LevelModel.Result result = model.forSkill(skill, xp);
			if (!result.isSecondHalf())
			{
				// game's number is already right
				continue;
			}

			// hovering a relabelled skill shows what it really is
			boolean reveal = revealOnHover && skill == hovered;
			String text = String.valueOf(reveal ? model.realFor(xp).getLevel() : result.getLevel());

			// while revealing, or with the tint off, put the original colour back
			int colour = tintOn && !reveal
				? tintColour
				: vanillaColour.getOrDefault(skill, NO_COLOUR);

			write(widget.getChild(CHILD_BASE_LEVEL), text, colour);

			// top number here is live hp and prayer points, not a level. never touch it.
			if (skill == Skill.HITPOINTS || skill == Skill.PRAYER)
			{
				continue;
			}

			// leave it alone while a boost is up so the boost stays visible
			if (client.getBoostedSkillLevel(skill) == client.getRealSkillLevel(skill))
			{
				write(widget.getChild(CHILD_CURRENT_LEVEL), text, colour);
			}
		}
	}

	// which skill the mouse is over, read off the tooltip. null if none.
	public Skill hoveredSkill()
	{
		Widget tip = client.getWidget(InterfaceID.Stats.TOOLTIP);
		if (tip == null || tip.isHidden())
		{
			return null;
		}

		Widget[] children = tip.getDynamicChildren();
		if (children == null || children.length <= TOOLTIP_VALUES)
		{
			return null;
		}

		Widget labels = children[TOOLTIP_LABELS];
		return labels == null || labels.getText() == null ? null : skillFromLabel(labels.getText());
	}

	public String totalLevelText(LevelModel model)
	{
		int total = 0;
		for (Skill skill : SKILL_WIDGETS.keySet())
		{
			int xp = client.getSkillExperience(skill);
			total += isSkillEnabled(skill)
				? model.forSkill(skill, xp).getLevel()
				: Experience.getLevelForXp(xp);
		}
		return "Total level: " + total;
	}

	// labels in one child, values in another, newline separated.
	// a maxed skill only has one line, so never assume three.
	public void renderTooltip(LevelModel model)
	{
		if (!config.tooltipSecondHalfXp())
		{
			return;
		}

		Widget tip = client.getWidget(InterfaceID.Stats.TOOLTIP);
		if (tip == null || tip.isHidden())
		{
			return;
		}

		Widget[] children = tip.getDynamicChildren();
		if (children == null || children.length <= TOOLTIP_VALUES)
		{
			return;
		}

		Widget labels = children[TOOLTIP_LABELS];
		Widget values = children[TOOLTIP_VALUES];
		if (labels == null || values == null || labels.getText() == null || values.getText() == null)
		{
			return;
		}

		Skill skill = skillFromLabel(labels.getText());
		if (skill == null || !isSkillEnabled(skill))
		{
			return;
		}

		int xp = client.getSkillExperience(skill);
		LevelModel.Result result = model.forSkill(skill, xp);
		if (!result.isSecondHalf())
		{
			// game's tooltip is already honest
			return;
		}

		writeRunXp(values, model, result, xp);
	}

	private void writeRunXp(Widget values, LevelModel model, LevelModel.Result result, int xp)
	{
		String[] lines = values.getText().split(LINE_BREAK);
		if (lines.length < 3)
		{
			return;
		}

		// gap to the next level is the same either way, only the total shifts
		int into = model.xpIntoRun(xp);
		int remaining = result.getXpAtNextLevel() - xp;

		String text = format(into) + LINE_BREAK + format(into + remaining) + LINE_BREAK + format(remaining);
		if (!text.equals(values.getText()))
		{
			values.setText(text);
		}
	}

	private static Skill skillFromLabel(String text)
	{
		int cut = text.indexOf(XP_LABEL);
		if (cut <= 0)
		{
			return null;
		}

		try
		{
			return Skill.valueOf(text.substring(0, cut).toUpperCase(Locale.ROOT));
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}

	private static String format(int value)
	{
		return String.format("%,d", value);
	}

	// a skill redraw won't put the colour back, so do it here
	public void restore()
	{
		for (Map.Entry<Skill, Integer> entry : vanillaColour.entrySet())
		{
			Integer widgetId = SKILL_WIDGETS.get(entry.getKey());
			Widget widget = widgetId == null ? null : client.getWidget(widgetId);
			if (widget == null)
			{
				continue;
			}

			recolour(widget.getChild(CHILD_CURRENT_LEVEL), entry.getValue());
			recolour(widget.getChild(CHILD_BASE_LEVEL), entry.getValue());
		}

		vanillaColour.clear();
	}

	// widgets gone under us, drop the refs without touching them
	public void reset()
	{
		vanillaColour.clear();
	}

	private void rememberColour(Skill skill, Widget widget, int ourColour)
	{
		if (vanillaColour.containsKey(skill))
		{
			return;
		}

		Widget base = widget.getChild(CHILD_BASE_LEVEL);
		// already ours, nothing original left to save
		if (base != null && base.getTextColor() != ourColour)
		{
			vanillaColour.put(skill, base.getTextColor());
		}
	}

	private static void recolour(Widget widget, int colour)
	{
		if (widget != null && widget.getTextColor() != colour)
		{
			widget.setTextColor(colour);
		}
	}

	private void write(Widget widget, String text, int colour)
	{
		if (widget == null)
		{
			return;
		}

		if (!text.equals(widget.getText()))
		{
			widget.setText(text);
		}

		if (colour != NO_COLOUR && widget.getTextColor() != colour)
		{
			widget.setTextColor(colour);
		}
	}

	public boolean isSkillEnabled(Skill skill)
	{
		switch (skill)
		{
			case ATTACK:
				return config.attack();
			case STRENGTH:
				return config.strength();
			case DEFENCE:
				return config.defence();
			case RANGED:
				return config.ranged();
			case MAGIC:
				return config.magic();
			case HITPOINTS:
				return config.hitpoints();
			case PRAYER:
				return config.prayer();
			case AGILITY:
				return config.agility();
			case CONSTRUCTION:
				return config.construction();
			case COOKING:
				return config.cooking();
			case CRAFTING:
				return config.crafting();
			case FARMING:
				return config.farming();
			case FIREMAKING:
				return config.firemaking();
			case FISHING:
				return config.fishing();
			case FLETCHING:
				return config.fletching();
			case HERBLORE:
				return config.herblore();
			case HUNTER:
				return config.hunter();
			case MINING:
				return config.mining();
			case RUNECRAFT:
				return config.runecraft();
			case SAILING:
				return config.sailing();
			case SLAYER:
				return config.slayer();
			case SMITHING:
				return config.smithing();
			case THIEVING:
				return config.thieving();
			case WOODCUTTING:
				return config.woodcutting();
			default:
				return false;
		}
	}

	// BarRenderer draws into the same tiles
	static Map<Skill, Integer> skillWidgets()
	{
		return SKILL_WIDGETS;
	}

	private static Map<Skill, Integer> buildSkillWidgets()
	{
		Map<Skill, Integer> map = new EnumMap<>(Skill.class);
		map.put(Skill.ATTACK, InterfaceID.Stats.ATTACK);
		map.put(Skill.STRENGTH, InterfaceID.Stats.STRENGTH);
		map.put(Skill.DEFENCE, InterfaceID.Stats.DEFENCE);
		map.put(Skill.RANGED, InterfaceID.Stats.RANGED);
		map.put(Skill.PRAYER, InterfaceID.Stats.PRAYER);
		map.put(Skill.MAGIC, InterfaceID.Stats.MAGIC);
		map.put(Skill.HITPOINTS, InterfaceID.Stats.HITPOINTS);
		map.put(Skill.RUNECRAFT, InterfaceID.Stats.RUNECRAFT);
		map.put(Skill.CONSTRUCTION, InterfaceID.Stats.CONSTRUCTION);
		map.put(Skill.AGILITY, InterfaceID.Stats.AGILITY);
		map.put(Skill.HERBLORE, InterfaceID.Stats.HERBLORE);
		map.put(Skill.THIEVING, InterfaceID.Stats.THIEVING);
		map.put(Skill.CRAFTING, InterfaceID.Stats.CRAFTING);
		map.put(Skill.FLETCHING, InterfaceID.Stats.FLETCHING);
		map.put(Skill.SLAYER, InterfaceID.Stats.SLAYER);
		map.put(Skill.HUNTER, InterfaceID.Stats.HUNTER);
		map.put(Skill.MINING, InterfaceID.Stats.MINING);
		map.put(Skill.SMITHING, InterfaceID.Stats.SMITHING);
		map.put(Skill.FISHING, InterfaceID.Stats.FISHING);
		map.put(Skill.COOKING, InterfaceID.Stats.COOKING);
		map.put(Skill.FIREMAKING, InterfaceID.Stats.FIREMAKING);
		map.put(Skill.WOODCUTTING, InterfaceID.Stats.WOODCUTTING);
		map.put(Skill.FARMING, InterfaceID.Stats.FARMING);
		map.put(Skill.SAILING, InterfaceID.Stats.SAILING);
		return Collections.unmodifiableMap(map);
	}
}

